package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Deterministic mission clocks. Deadlines create explicit consequence envelopes; they never invent rewards or damage. */
public final class MissionDeadlineEngine{
 private MissionDeadlineEngine(){}
 public static JSONObject schedule(JSONObject mission,int currentDay){JSONObject o=copy(mission);try{int due=o.optInt("due_day",0);o.put("created_day",Math.max(1,currentDay)).put("status",o.optString("status","active"));if(due>0)o.put("days_remaining",Math.max(0,due-currentDay));}catch(Exception ignored){}return o;}
 public static JSONObject tick(JSONObject mission,int day){JSONObject o=copy(mission);try{String status=o.optString("status","active");if("completed".equals(status)||"failed".equals(status)||"cancelled".equals(status))return o;int due=o.optInt("due_day",0);if(due<=0)return o;int left=due-day;o.put("days_remaining",Math.max(0,left));if(left<0)o.put("status","overdue").put("overdue_days",-left).put("consequence_pending",true);else if(left==0)o.put("status","due_today").put("overdue_days",0);else o.put("status","active").put("overdue_days",0).put("consequence_pending",false);}catch(Exception ignored){}return o;}
 public static JSONObject resolve(JSONObject mission,String status,String summary,int day){JSONObject o=copy(mission);String s=status==null?"":status.trim().toLowerCase();if(!("completed".equals(s)||"failed".equals(s)||"cancelled".equals(s)))throw new IllegalArgumentException("mission terminal status required");try{o.put("status",s).put("resolved_day",Math.max(1,day)).put("consequence_pending",false).put("overdue_days",Math.max(0,o.optInt("overdue_days",0)));if(summary!=null&&!summary.trim().isEmpty())o.put("resolution_summary",summary.trim());}catch(Exception ignored){}return o;}
 public static JSONObject consequenceEnvelope(JSONObject mission,int day){JSONObject x=new JSONObject();try{JSONObject m=tick(mission,day);if(!m.optBoolean("consequence_pending",false))return x;x.put("mission_key",m.optString("key")).put("deadline_day",m.optInt("due_day",0)).put("overdue_days",m.optInt("overdue_days",0)).put("procedure_json",m.optJSONObject("deadline_procedure") == null?new JSONObject():m.optJSONObject("deadline_procedure")).put("requires_compiled_rule",true).put("auto_apply",false);}catch(Exception ignored){}return x;}
 private static JSONObject copy(JSONObject o){try{return o==null?new JSONObject():new JSONObject(o.toString());}catch(Exception e){return new JSONObject();}}
}
